#include <iostream>
using namespace std;

long long sideSum(long long peak, long long length) {
    long long decreasing = min(length, peak - 1);
    long long sum = decreasing * (2 * peak - decreasing - 1) / 2;
    return sum + (length - decreasing);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m, k;
    cin >> n >> m >> k;

    long long low = 1, high = m, answer = 1;

    while (low <= high) {
        long long peak = low + (high - low) / 2;
        long long total = peak
                        + sideSum(peak, k - 1)
                        + sideSum(peak, n - k);

        if (total <= m) {
            answer = peak;
            low = peak + 1;
        } else {
            high = peak - 1;
        }
    }

    cout << answer;
    return 0;
}

